public static class GroupingTest {
 static readonly BindingFlags editorFlags=BindingFlags.Instance|BindingFlags.NonPublic;
 static object EF(Editor e,string name){return typeof(Editor).GetField(name,editorFlags).GetValue(e);}
 static void ES(Editor e,string name,object value){typeof(Editor).GetField(name,editorFlags).SetValue(e,value);}
 static object EI(Editor e,string name,params object[] values){return typeof(Editor).GetMethod(name,editorFlags).Invoke(e,values);}
 static Project EP(Editor e){return (Project)EF(e,"project");}
 static int UndoCount(Editor e){return ((Stack<string>)EF(e,"undo")).Count;}
 static HashSet<string> Selection(Editor e){return (HashSet<string>)EF(e,"selectedClipIds");}
 static void ResetEditor(Editor e,Project p){ES(e,"project",Clone(p));ES(e,"selected",null);Selection(e).Clear();ES(e,"openedGroupId",null);ES(e,"dirty",false);((Stack<string>)EF(e,"undo")).Clear();((Stack<string>)EF(e,"redo")).Clear();EI(e,"Refresh");}
 static string root,log;static int passed;static LivePreview preview;static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 static void Near(double a,double b,string name){Require(Math.Abs(a-b)<.000001,name);}
 static void Require(bool ok,string name){if(!ok)throw new Exception(name);passed++;File.AppendAllText(log,"PASS "+name+Environment.NewLine);}
 static void Reject(Action action,string name){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(InvalidOperationException){rejected=true;}catch(InvalidDataException){rejected=true;}Require(rejected,name);}
 static Project Clone(Project p){return json.Deserialize<Project>(json.Serialize(p));}
 static string ClipState(Project p){return json.Serialize(p.Clips);}
 static void Order(IEnumerable<Clip> actual,IEnumerable<Clip> expected,string name){Require(actual.Select(c=>c.Id).SequenceEqual(expected.Select(c=>c.Id)),name);}
 static void Fixture(string path,bool split){using(var b=new System.Drawing.Bitmap(320,180)){using(var g=System.Drawing.Graphics.FromImage(b)){g.Clear(split?System.Drawing.Color.Red:System.Drawing.Color.Lime);if(split)g.FillRectangle(System.Drawing.Brushes.Blue,160,0,160,180);}b.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
 static byte[] Preview(Project p,double time){preview.SetProject(p);preview.Seek(time);preview.UpdateLayout();var b=new RenderTargetBitmap(320,180,96,96,PixelFormats.Pbgra32);b.Render(preview.Stage);var pixels=new byte[320*180*4];b.CopyPixels(pixels,320*4,0);return pixels;}
 static byte[][] Export(Project p,string name){string video=Path.Combine(root,name+".mp4");Engine.Render(p,video,null);var frames=new List<byte[]>();foreach(double time in new[]{.3,1.2}){string png=Path.Combine(root,name+"-"+time.ToString(System.Globalization.CultureInfo.InvariantCulture)+".png");Engine.Run("ffmpeg","-y -v error -ss "+time.ToString(System.Globalization.CultureInfo.InvariantCulture)+" -i "+Engine.Quote(video)+" -frames:v 1 -threads 1 "+Engine.Quote(png));using(var b=new System.Drawing.Bitmap(png)){Require(b.Width==320&&b.Height==180,name+" decoded dimensions at "+time);var pixels=new byte[320*180*3];for(int y=0;y<180;y++)for(int x=0;x<320;x++){var color=b.GetPixel(x,y);int n=(y*320+x)*3;pixels[n]=color.R;pixels[n+1]=color.G;pixels[n+2]=color.B;}frames.Add(pixels);}}return frames.ToArray();}
 static void BadMetadata(Project source,Action<Project> change,string name){var p=Clone(source);change(p);Reject(()=>Engine.Validate(p,false),name);}
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application();preview=new LivePreview();var window=new Window{Width=800,Height=600,Content=preview,Title="TatsiaCraft isolated group acceptance"};window.Loaded+=async(s,e)=>{try{
  string split=Path.Combine(root,"split.png"),background=Path.Combine(root,"green.png");Fixture(split,true);Fixture(background,false);var media=Engine.Probe(split);var green=Engine.Probe(background);var p=new Project{Width=320,Height=180,TrackCount=4};p.Media.Add(green);p.Media.Add(media);var lower=new Clip{MediaId=green.Id,NativeSize=true,Duration=2};var first=new Clip{MediaId=media.Id,NativeSize=true,Start=.1,Duration=.5,Track=1,Scale=.75,X=-30,Y=-10,Rotation=33,CropLeft=.125,CropTop=.1,CropRight=.2,CropBottom=.15,Volume=.8,Speed=1.5};var second=new Clip{MediaId=media.Id,NativeSize=true,Start=.9,Duration=.7,Track=2,Scale=.5,X=50,Y=20,Rotation=90,CropLeft=.1,CropTop=.125,CropBottom=.125};p.Clips.AddRange(new[]{lower,first,second});Engine.Validate(p,true);string clipState=ClipState(p);var beforeA=Preview(p,.3);await Task.Delay(50);beforeA=Preview(p,.3);var beforeB=Preview(p,1.2);var exportBefore=Export(p,"before-group");
