  var moved=Clone(reopened);var movedFirst=moved.Clips[1];var movedSecond=moved.Clips[2];string moveBefore=json.Serialize(moved);var move=new ClipMoveOperation(moved,ClipGroups.Expand(moved,new[]{movedFirst}));var canvasMove=move.EvaluateCanvas(25,-15);Require(canvasMove.Changes,"unit canvas translation reports pending change");Require(json.Serialize(moved)==moveBefore,"unit canvas evaluation is pure");canvasMove.Apply();Near(movedFirst.X,first.X+25,"unit canvas first X translated");Near(movedSecond.X,second.X+25,"unit canvas second X translated");Near(movedFirst.Y,first.Y-15,"unit canvas first Y translated");Near(movedSecond.Y,second.Y-15,"unit canvas second Y translated");Near(movedSecond.X-movedFirst.X,second.X-first.X,"unit canvas spacing X preserved");Near(movedSecond.Y-movedFirst.Y,second.Y-first.Y,"unit canvas spacing Y preserved");Require(!canvasMove.Changes,"applied canvas result reports no remaining change");var expectedMoved=Clone(reopened);expectedMoved.Clips[1].X+=25;expectedMoved.Clips[2].X+=25;expectedMoved.Clips[1].Y-=15;expectedMoved.Clips[2].Y-=15;Require(json.Serialize(moved)==json.Serialize(expectedMoved),"canvas unit move changes only selected position fields");move.EvaluateCanvas(10,5).Apply();Near(movedFirst.X,first.X+10,"gesture updates use original snapshot rather than accumulating");Near(movedSecond.X,second.X+10,"snapshot update applies equally to sibling");
